            <div className="w-full max-w-md h-[70vh] flex flex-col">
              <h2 className="text-4xl font-black mb-8 uppercase text-amber-500">Los Mejores Pilotos</h2>
              <div className="flex-1 overflow-y-auto bg-slate-900/50 border border-white/5 rounded-3xl p-2 scrollbar-hide">
                {leaderboard.length > 0 ? (
                  <table className="w-full text-left">
                    <thead><tr className="border-b border-white/5"><th className="p-4 text-[10px] text-slate-500 uppercase">#</th><th className="p-4 text-[10px] text-slate-500 uppercase">Nombre</th><th className="p-4 text-[10px] text-slate-500 text-right uppercase">Pts</th></tr></thead>
                    <tbody>
                      {leaderboard.map((r, i) => <tr key={i} className="border-b border-white/5"><td className="p-4 font-black text-slate-700">{i+1}</td><td className="p-4 font-bold text-white">{r.name}</td><td className="p-4 font-black text-blue-400 text-right">{r.score.toLocaleString()}</td></tr>)}
                    </tbody>
                  </table>
                ) : <div className="p-20 text-slate-700 uppercase font-black">Vacio</div>}
              </div>
              <button onClick={() => setGameState('menu')} className="mt-8 py-4 bg-slate-800 rounded-2xl font-black uppercase text-xs">Cerrar</button>
            </div>
          </div>
        )}

        {gameState === 'tutorial' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950/95 backdrop-blur-3xl p-6 text-center z-50 animate-in fade-in duration-300">
            <button onClick={() => setGameState('menu')} className="absolute top-8 right-8 p-3 bg-white/5 rounded-full"><X className="w-6 h-6"/></button>
            <div className="max-w-md w-full flex flex-col items-center">
              <div className="mb-8 p-12 bg-blue-600/20 rounded-[4rem] border border-blue-500/30 animate-pulse">{tutorialSteps[tutorialStep].icon}</div>
              <h2 className="text-4xl font-black mb-4 uppercase text-blue-400 tracking-tighter">{tutorialSteps[tutorialStep].title}</h2>
              <p className="text-slate-400 text-xl leading-relaxed mb-10">{tutorialSteps[tutorialStep].desc}</p>
              <div className="flex items-center gap-6 w-full justify-between"><button disabled={tutorialStep === 0} onClick={() => setTutorialStep(s => s - 1)} className="p-5 bg-slate-800 rounded-2xl disabled:opacity-20 active:scale-90 transition-all"><ChevronLeft/></button><div className="flex gap-2">{tutorialSteps.map((_, i) => <div key={i} className={`h-2 rounded-full transition-all ${i === tutorialStep ? 'w-10 bg-blue-500' : 'w-2 bg-slate-800'}`} />)}</div>{tutorialStep < tutorialSteps.length - 1 ? <button onClick={() => setTutorialStep(s => s + 1)} className="p-5 bg-blue-600 rounded-2xl active:scale-90 transition-all"><ChevronRight/></button> : <button onClick={() => setGameState('menu')} className="px-10 py-5 bg-emerald-600 rounded-2xl font-black text-xs uppercase shadow-2xl active:scale-90 transition-all">Listo</button>}</div>
            </div>
          </div>
        )}
      </div>

      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;700;900&display=swap');
        body { margin: 0; background: #020617; font-family: 'Inter', sans-serif; cursor: crosshair; user-select: none; overflow: hidden; }
        canvas { display: block; image-rendering: pixelated; }
        .animate-bounce-slow { animation: bounce 4s infinite ease-in-out; }
        @keyframes bounce { 0%, 100% { transform: translateY(-3%); } 50% { transform: translateY(0); } }
        .scrollbar-hide::-webkit-scrollbar { display: none; }
        .scrollbar-hide { -ms-overflow-style: none; scrollbar-width: none; }
        input::-webkit-outer-spin-button, input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
        input[type=number] { -moz-appearance: textfield; }
        @keyframes pulse-glow { 
          0%, 100% { box-shadow: 0 0 15px -5px rgba(59, 130, 246, 0.3); border-color: rgba(59, 130, 246, 0.3); transform: scale(1); } 
          50% { box-shadow: 0 0 30px -5px rgba(59, 130, 246, 0.6); border-color: rgba(59, 130, 246, 0.8); transform: scale(1.02); } 
        }
        .animate-pulse-glow { animation: pulse-glow 3s infinite ease-in-out; }
      `}</style>
    </div>
  );
};

const root = document.getElementById('root');
if (root) createRoot(root).render(<ZumaMathGame />);

import React, { useState, useEffect, useRef, useCallback, useLayoutEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { Target, Zap, Play, RotateCcw, Home, HelpCircle, Trophy, AlertTriangle, BookOpen, ChevronRight, ChevronLeft, X, ListOrdered, Save, User, Pause, PlayCircle, ArrowRight, CheckCircle2, AlertCircle, Sparkles, MousePointer2, Flame } from 'lucide-react';

// --- Constants & Types ---

type GameMode = 'multiples' | 'divisors';
type GameState = 'menu' | 'playing' | 'gameover' | 'victory' | 'tutorial' | 'leaderboard' | 'flowchart';

interface Point {
  x: number;
  y: number;
}

interface Ball {
  id: number;
  value: number;
  pos: number; // 0 to 1 along the path
  color: string;
}

interface Projectile {
  x: number;
  y: number;
  vx: number;
  vy: number;
  value: number;
}

interface Effect {
  type: 'particle' | 'text' | 'combo' | 'ui';
  x: number;
  y: number;
  vx?: number;
  vy?: number;
  life: number;
  maxLife: number;
  text?: string;
  color: string;
  size?: number;
}

interface ScoreRecord {
  name: string;
  score: number;
  mode: string;
  target: number;
  date: string;
}

const COLORS = ['#f43f5e', '#06b6d4', '#8b5cf6', '#10b981', '#f59e0b'];
const BALL_RADIUS = 20;
const PROJECTILE_SPEED = 18;
const PATH_SAMPLES = 1000;
const INITIAL_SPEED = 0.00035;
const SPEED_INCREMENT = 0.00008;
const ENERGY_GAIN = 20; 
const ENERGY_LOSS = 25;

// --- Utility Functions ---

const getRandomInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

const getConditionMatch = (val: number, target: number, mode: GameMode): boolean => {
  if (mode === 'multiples') return val % target === 0;
  return val !== 0 && target % val === 0;
};

const generatePath = (width: number, height: number): Point[] => {
  const points: Point[] = [];
  const centerX = width / 2;
  const centerY = height / 2;
  const maxRadius = Math.min(width, height) * 0.44;
  const loops = 3;

  for (let i = 0; i <= PATH_SAMPLES; i++) {
    const t = i / PATH_SAMPLES;
    const angle = t * Math.PI * 2 * loops;
    const radius = maxRadius * (1 - t * 0.86);
    points.push({
      x: centerX + Math.cos(angle) * radius,
      y: centerY + Math.sin(angle) * radius,
    });
  }
  return points;
};

// --- Main Component ---

const ZumaMathGame = () => {
  const [gameState, setGameState] = useState<GameState>('menu');
  const [isPaused, setIsPaused] = useState(false);
  const [gameMode, setGameMode] = useState<GameMode>('multiples');
  const [targetNumber, setTargetNumber] = useState<number>(5);
  const [customTarget, setCustomTarget] = useState<string>('');
  const [score, setScore] = useState<number>(0);
  const [energy, setEnergy] = useState<number>(0);
  const [level, setLevel] = useState<number>(1);
  const [leaderboard, setLeaderboard] = useState<ScoreRecord[]>([]);
  const [playerName, setPlayerName] = useState<string>('');
  const [scoreSaved, setScoreSaved] = useState<boolean>(false);
  const [dimensions, setDimensions] = useState({ width: window.innerWidth, height: window.innerHeight });
  const [tutorialStep, setTutorialStep] = useState<number>(0);
  const [comboDisplay, setComboDisplay] = useState<number>(0);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const requestRef = useRef<number>(0);
  const pathRef = useRef<Point[]>([]);
  const ballsRef = useRef<Ball[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const effectsRef = useRef<Effect[]>([]);
  const shooterAngleRef = useRef<number>(0);
  const nextBallValueRef = useRef<number>(5);
  const currentBallValueRef = useRef<number>(5);
  const gameSpeedRef = useRef<number>(INITIAL_SPEED);
  const ballCounterRef = useRef<number>(0);
  const screenShakeRef = useRef<number>(0);
  const swapCooldownRef = useRef<number>(0);
  const comboRef = useRef<number>(0);
  const comboTimerRef = useRef<any>(null);

  // Continuous Spawning Refs
  const ballsSpawnedRef = useRef<number>(0);
  const maxBallsRef = useRef<number>(0);

  useLayoutEffect(() => {
    const updateSize = () => {
      if (containerRef.current) {
        const { clientWidth, clientHeight } = containerRef.current;
        setDimensions({ width: clientWidth, height: clientHeight });
        pathRef.current = generatePath(clientWidth, clientHeight);
      }
    };
    window.addEventListener('resize', updateSize);
    updateSize();
    return () => window.removeEventListener('resize', updateSize);
  }, []);

  const spawnParticles = (x: number, y: number, color: string, count = 10) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 6 + 2;
      effectsRef.current.push({
        type: 'particle', x, y,
        vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed,
        life: 1, maxLife: 1, color, size: Math.random() * 4 + 2,
      });
    }
  };

  const spawnText = (x: number, y: number, text: string, color: string, size = 20, type: 'text' | 'combo' | 'ui' = 'text') => {
    effectsRef.current.push({
      type, x, y, vy: type === 'ui' ? 0 : -1.8,
      life: 1, maxLife: 1, text, color, size,
    });
  };

  const generateFairValue = (target: number, mode: GameMode, lvl: number, force?: 'match' | 'no-match'): number => {
    const matchProb = Math.max(0.75, 0.96 - (lvl - 1) * 0.04);
    const shouldMatch = force === 'match' ? true : (force === 'no-match' ? false : Math.random() < matchProb);

    if (mode === 'multiples') {
      if (shouldMatch) return target * getRandomInt(1, 10);
      let val = getRandomInt(1, 50);
      for (let i = 0; i < 5 && val % target === 0; i++) val = getRandomInt(1, 50);
      return val;
    } else {
      const divisors = [];
      for (let i = 1; i <= target; i++) if (target % i === 0) divisors.push(i);
      if (shouldMatch && divisors.length > 0) return divisors[getRandomInt(0, divisors.length - 1)];
      let val = getRandomInt(1, target + 10);
      for (let i = 0; i < 5 && (val !== 0 && target % val === 0); i++) val = getRandomInt(1, target + 10);
      return val;
    }
  };

  const handleSwap = useCallback(() => {
    if (gameState !== 'playing' || isPaused || Date.now() < swapCooldownRef.current) return;
    const temp = currentBallValueRef.current;
    currentBallValueRef.current = nextBallValueRef.current;
    nextBallValueRef.current = temp;
    swapCooldownRef.current = Date.now() + 200;
    spawnText(dimensions.width / 2, dimensions.height / 2 - 85, "¡CAMBIO!", "#0ea5e9", 14, "ui");
  }, [gameState, isPaused, dimensions]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => { if (e.code === 'Space') { e.preventDefault(); handleSwap(); } };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [handleSwap]);

  const initLevel = (lvl: number, mode: GameMode, chosenTarget?: number) => {
    let target = chosenTarget || targetNumber;
    if (!chosenTarget) {
      if (mode === 'multiples') target = getRandomInt(2, 9);
      else target = [12, 16, 20, 24, 30, 36, 48, 60][getRandomInt(0, 7)];
    }
    setTargetNumber(target);
    setScore(0);
    setEnergy(0);
    setLevel(lvl);
    setScoreSaved(false);
    setIsPaused(false);
    gameSpeedRef.current = INITIAL_SPEED + (lvl - 1) * SPEED_INCREMENT;
    projectilesRef.current = [];
    effectsRef.current = [];
    comboRef.current = 0;
    setComboDisplay(0);
    if (comboTimerRef.current) clearTimeout(comboTimerRef.current);

    // Continuous spawning setup
    maxBallsRef.current = 20 + lvl * 5; // Total balls for this level
    ballsSpawnedRef.current = 0;

    const initialBalls: Ball[] = [];
    // Spawn only a small batch initially to fill the start of the screen
    const initialBatchSize = 10;
    for (let i = 0; i < initialBatchSize; i++) {
      initialBalls.push({
        id: ballCounterRef.current++,
        value: generateFairValue(target, mode, lvl, 'match'),
        pos: -i * 0.045,
        color: COLORS[getRandomInt(0, COLORS.length - 1)],
      });
      ballsSpawnedRef.current++;
    }
    ballsRef.current = initialBalls;
    currentBallValueRef.current = generateFairValue(target, mode, lvl, 'match');
    nextBallValueRef.current = generateFairValue(target, mode, lvl, 'match');
  };

  const onMove = (e: any) => {
    if (isPaused || gameState !== 'playing') return;
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect) return;
    const x = (e.clientX || e.touches?.[0]?.clientX) - rect.left;
    const y = (e.clientY || e.touches?.[0]?.clientY) - rect.top;
    shooterAngleRef.current = Math.atan2(y - dimensions.height / 2, x - dimensions.width / 2);
  };

  const onShoot = (e: any) => {
    if (gameState !== 'playing' || isPaused) return;
    if (e.button === 2) { e.preventDefault(); handleSwap(); return; }

    const angle = shooterAngleRef.current;
    projectilesRef.current.push({
      x: dimensions.width / 2 + Math.cos(angle) * 45,
      y: dimensions.height / 2 + Math.sin(angle) * 45,
      vx: Math.cos(angle) * PROJECTILE_SPEED,
      vy: Math.sin(angle) * PROJECTILE_SPEED,
      value: currentBallValueRef.current,
    });

    const totalBalls = ballsRef.current.length;
    // Smart Ammo: If few balls remain ON SCREEN, force the next ammo to be valid to prevent stuck games
    const force = totalBalls < 5 ? 'match' : undefined;

    currentBallValueRef.current = nextBallValueRef.current;
    nextBallValueRef.current = generateFairValue(targetNumber, gameMode, level, force as any);
  };

  const handleHit = (hitBall: Ball, shotValue: number, ballIndex: number) => {
    const isShotMatch = getConditionMatch(shotValue, targetNumber, gameMode);

    const pIdx = Math.max(0, Math.min(PATH_SAMPLES - 1, Math.floor(hitBall.pos * (PATH_SAMPLES - 1))));
    const p = pathRef.current[pIdx];

    if (isShotMatch) {
      let toRemove = [ballIndex];
      const MAX_CLEAR = 2; // Extra balls to clear
      for (let j = 1; j <= MAX_CLEAR; j++) {
        if (ballIndex + j < ballsRef.current.length) toRemove.push(ballIndex + j);
        if (ballIndex - j >= 0) toRemove.push(ballIndex - j);
      }

      comboRef.current += 1;
      setComboDisplay(comboRef.current);
      if (comboTimerRef.current) clearTimeout(comboTimerRef.current);
      comboTimerRef.current = setTimeout(() => {
        comboRef.current = 0;
        setComboDisplay(0);
      }, 4000);

      const comboMultiplier = comboRef.current;
      const points = toRemove.length * 100 * comboMultiplier;

      setScore(s => s + points);
      setEnergy(e => Math.min(100, e + ENERGY_GAIN));
      toRemove.forEach(idx => {
        const b = ballsRef.current[idx];
        if(!b) return;
        const bp = pathRef.current[Math.max(0, Math.floor(b.pos * (PATH_SAMPLES - 1)))];
        if (bp) spawnParticles(bp.x, bp.y, b.color, 12);
      });

      const comboText = comboMultiplier > 1 ? `COMBO x${comboMultiplier}!` : `+${points}`;
      spawnText(p.x, p.y - 30, comboText, comboMultiplier > 1 ? '#f59e0b' : '#fff', comboMultiplier > 1 ? 32 : 24, comboMultiplier > 1 ? 'combo' : 'text');

      screenShakeRef.current = toRemove.length * 3 + (comboMultiplier > 1 ? 5 : 0);
      ballsRef.current = ballsRef.current.filter((_, idx) => !toRemove.includes(idx));

    } else {
      if (comboRef.current > 1) {
        spawnText(p.x, p.y - 60, "COMBO LOST", "#f43f5e", 24, 'text');
      }
      comboRef.current = 0;
      setComboDisplay(0);
      if (comboTimerRef.current) clearTimeout(comboTimerRef.current);

      setEnergy(e => Math.max(0, e - ENERGY_LOSS));
      spawnText(p.x, p.y - 30, "¡INCORRECTO!", "#f43f5e", 24, 'text');
      spawnParticles(p.x, p.y, "#f43f5e", 8); 
      screenShakeRef.current = 8;
    }
  };

  const update = () => {
    if (gameState !== 'playing' || isPaused) { 
      requestRef.current = requestAnimationFrame(update); 
      return; 
    }

    // --- Continuous Spawning Logic ---
    if (ballsSpawnedRef.current < maxBallsRef.current) {
      let spawnPos: number | null = null;

      if (ballsRef.current.length === 0) {
        // If board cleared but quota not met, spawn new at start
        spawnPos = -0.045;
      } else {
        // Find the "tail" ball (smallest pos)
        let tailBall = ballsRef.current[0];
        for (const b of ballsRef.current) {
          if (b.pos < tailBall.pos) tailBall = b;
        }

        // If tail has moved in, attach new ball
        if (tailBall.pos > -0.05) {
           // Ensure we don't spawn mid-path if tail is far ahead
           // If tail is at 0.5, we spawn at -0.045 (start new chain)
           // If tail is at 0.0, we spawn at -0.045 (attach)
           // If tail is at -0.02, we spawn at -0.065 (attach)
           spawnPos = Math.min(-0.045, tailBall.pos - 0.045);
        }
      }

      if (spawnPos !== null) {
        ballsRef.current.push({
          id: ballCounterRef.current++,
          value: generateFairValue(targetNumber, gameMode, level, 'match'),
          pos: spawnPos,
          color: COLORS[getRandomInt(0, COLORS.length - 1)],
        });
        ballsSpawnedRef.current++;
      }
    }
    // --------------------------------

    // Move balls
    let gameOver = false;
    for (const b of ballsRef.current) {
      b.pos += gameSpeedRef.current;
      if (b.pos >= 1) { gameOver = true; break; }
    }
    if (gameOver) { setGameState('gameover'); return; }

    // Update projectiles & Collisions
    const nextProjectiles: Projectile[] = [];
    for (const p of projectilesRef.current) {
      p.x += p.vx;
      p.y += p.vy;

      let collided = false;
      if (p.x < 0 || p.x > dimensions.width || p.y < 0 || p.y > dimensions.height) {
        collided = true; // Just treat out of bounds as removal
      } else {
        for (let i = 0; i < ballsRef.current.length; i++) {
          const b = ballsRef.current[i];
          if (b.pos < 0) continue;
          const bp = pathRef.current[Math.floor(b.pos * (PATH_SAMPLES - 1))];
          if (bp && (p.x - bp.x)**2 + (p.y - bp.y)**2 < (BALL_RADIUS * 1.7)**2) {
            handleHit(b, p.value, i);
            collided = true;
            break;
          }
        }
      }
      if (!collided) nextProjectiles.push(p);
    }
    projectilesRef.current = nextProjectiles;

    // Effects & Cleanup
    effectsRef.current = effectsRef.current.filter(e => {
      e.life -= 0.025;
      e.x += (e.vx || 0);
      e.y += (e.vy || 0);
      return e.life > 0;
    });

    if (screenShakeRef.current > 0) screenShakeRef.current -= 0.5;

    // Victory Condition: All balls cleared AND quota met
    if (ballsRef.current.length === 0 && ballsSpawnedRef.current >= maxBallsRef.current) {
       setGameState('victory');
    }

    draw();
    requestRef.current = requestAnimationFrame(update);
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d', { alpha: false });
    if (!ctx || !canvas) return;

    ctx.save();
    if (screenShakeRef.current > 0) ctx.translate((Math.random()-0.5)*screenShakeRef.current, (Math.random()-0.5)*screenShakeRef.current);

    ctx.fillStyle = '#020617';
    ctx.fillRect(0, 0, dimensions.width, dimensions.height);

    // Path
    ctx.beginPath();
    ctx.strokeStyle = 'rgba(255,255,255,0.04)';
    ctx.lineWidth = 44;
    ctx.lineCap = 'round';
    pathRef.current.forEach((p, i) => i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y));
    ctx.stroke();

    // End Goal
    const ep = pathRef.current[PATH_SAMPLES];
    if (ep) {
      ctx.beginPath();
      ctx.fillStyle = '#000';
      ctx.arc(ep.x, ep.y, 30 + Math.sin(Date.now()/150)*5, 0, Math.PI*2);
      ctx.fill();
      ctx.strokeStyle = '#f43f5e';
      ctx.lineWidth = 4;
      ctx.stroke();
    }

    // Balls
    ballsRef.current.forEach(b => {
      if (b.pos < 0 || b.pos > 1) return;
      const p = pathRef.current[Math.floor(b.pos * (PATH_SAMPLES-1))];
      if (!p) return;
      const match = getConditionMatch(b.value, targetNumber, gameMode);

      ctx.beginPath();
      ctx.fillStyle = b.color;
      ctx.arc(p.x, p.y, BALL_RADIUS, 0, Math.PI*2);
      ctx.fill();
      // All board balls match now, but we keep visuals
      if (match) {
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 3;
        ctx.stroke();
      }
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 15px Inter';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(b.value.toString(), p.x, p.y);
    });

    // Projectiles
    projectilesRef.current.forEach(p => {
      ctx.beginPath();
      ctx.fillStyle = '#fff';
      ctx.arc(p.x, p.y, 14, 0, Math.PI*2);
      ctx.fill();
      ctx.fillStyle = '#000';
      ctx.font = 'bold 13px Inter';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(p.value.toString(), p.x, p.y);
    });

    // Effects
    effectsRef.current.forEach(e => {
      ctx.globalAlpha = e.life;
      if (e.type === 'particle') {
        ctx.beginPath(); ctx.fillStyle = e.color; ctx.arc(e.x, e.y, e.size || 3, 0, Math.PI*2); ctx.fill();
      } else {
        ctx.fillStyle = e.color;
        ctx.font = `black ${e.type === 'combo' ? 38 : (e.size || 20)}px Inter`;
        ctx.textAlign = 'center';
        ctx.fillText(e.text || '', e.x, e.y);
      }
    });
    ctx.globalAlpha = 1;

    // --- SHOOTER UI ---
    const cx = dimensions.width / 2;
    const cy = dimensions.height / 2;

    // Rule Indicator (above turret)
    ctx.textAlign = 'center';
    ctx.font = 'black 12px Inter';
    ctx.fillStyle = '#38bdf8';
    ctx.fillText('REGLA:', cx, cy - 90);
    ctx.fillStyle = '#fff';
    ctx.font = 'black 22px Inter';
    const missionText = `${gameMode === 'multiples' ? 'MÚLTIPLOS' : 'DIVISORES'} DE ${targetNumber}`;
    // Pulsing effect for rule
    ctx.globalAlpha = 0.8 + Math.sin(Date.now() / 200) * 0.2;
    ctx.fillText(missionText, cx, cy - 65);
    ctx.globalAlpha = 1;

    // Turret barrel
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(shooterAngleRef.current);
    ctx.fillStyle = '#1e293b';
    ctx.beginPath(); ctx.roundRect(-22, -18, 65, 36, 12); ctx.fill();
    ctx.fillStyle = '#0ea5e9'; ctx.fillRect(38, -6, 10, 12);
    ctx.restore();

    // Turret Core
    ctx.beginPath();
    ctx.fillStyle = '#0f172a';
    ctx.strokeStyle = energy === 100 ? '#f59e0b' : '#0ea5e9';
    ctx.lineWidth = 5;
    ctx.arc(cx, cy, 40, 0, Math.PI*2);
    ctx.fill(); ctx.stroke();

    // Bala Label
    ctx.fillStyle = '#38bdf8';
    ctx.font = 'black 9px Inter';
    ctx.fillText('BALA', cx, cy - 22);

    // Projectile Value (Number in the middle)
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 30px Inter';
    ctx.fillText(currentBallValueRef.current.toString(), cx, cy + 5);

    // Next Ball indicator
    ctx.font = 'black 11px Inter'; ctx.fillStyle = '#0ea5e9';
    ctx.fillText('SIGUIENTE: ' + nextBallValueRef.current.toString(), cx, cy + 62);

    if (isPaused) { 
      ctx.fillStyle = 'rgba(2,6,23,0.8)'; ctx.fillRect(0,0,dimensions.width,dimensions.height); 
      ctx.fillStyle='#fff'; ctx.font='black 60px Inter'; ctx.fillText("PAUSA", cx, cy); 
    }
    ctx.restore();
  }, [gameState, targetNumber, gameMode, isPaused, energy, dimensions]);

  useEffect(() => {
    if (gameState === 'playing') requestRef.current = requestAnimationFrame(update);
