        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        @keyframes flash-danger { 
          0%, 100% { background-color: #ef4444; box-shadow: 0 0 10px #ef4444; } 
          50% { background-color: #f87171; box-shadow: 0 0 20px #f87171; } 
